import { c as galleryImages } from "../../../chunks/db.js";
import { r as getHero, u as list } from "../../../chunks/content.js";
//#region src/routes/gallery/+page.server.ts
var load = async () => {
	const [hero, images] = await Promise.all([getHero("gallery"), list(galleryImages)]);
	return {
		hero,
		images: images.filter((image) => image.context !== "hero").map((image) => ({
			id: image.id,
			src: image.src,
			alt: image.altText,
			caption: image.caption,
			place: image.place,
			context: image.context
		}))
	};
};
//#endregion
export { load };
